data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

resource "aws_lightsail_disk" "test" {
  name              = "test-disk"
  size_in_gb        = 8
  availability_zone = data.aws_availability_zones.available.names[0]
}

resource "aws_lightsail_instance" "test" {
  name              = "test-instance"
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "nano_1_0"
}

resource "aws_lightsail_disk_attachment" "test" {
  disk_name     = aws_lightsail_disk.test.name
  instance_name = aws_lightsail_instance.test.name
  disk_path     = "/dev/xvdf"
}

responsePreview:
This Terraform configuration creates an AWS Lightsail compute instance and a separate Lightsail block storage disk, then attaches the disk to the instance. It uses the AWS provider in `us-east-1`, creates an Ubuntu Lightsail instance, provisions an additional storage disk in the same Availability Zone, and links the disk to the compute service using a Lightsail disk attachment.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where Lightsail resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability Zone for the Lightsail instance and disk."
  type        = string
  default     = "us-east-1a"
}

variable "instance_name" {
  description = "Name of the Lightsail compute instance."
  type        = string
  default     = "lightsail-compute-service"
}

variable "disk_name" {
  description = "Name of the Lightsail storage disk."
  type        = string
  default     = "lightsail-storage-unit"
}

